// Pass artwork, base64. Apple silently rejects a .pkpass missing icon.png.
//
// The pass is `generic`, not `eventTicket` — see convex/wallet/pkpass.ts for
// why. generic supports icon, logo and thumbnail, but NOT background.png or
// strip.png, so the invite poster overlay (rings, disc, arcs, grain, no
// photograph) rides in thumbnail.* as a square.
//
// logo.png stacks the cream academix wordmark over MIX & GREET: Wallet draws
// logoText to the RIGHT of the logo with no way to place it below, and at full
// width the wordmark ran under the top notch.
export const PASS_IMAGES: Record<string, string> = {
  "icon.png": "",
  "icon@2x.png": "",
  "icon@3x.png": "",
  "logo.png": "",
  "logo@2x.png": "",
  "logo@3x.png": "",
  "thumbnail.png": "",
  "thumbnail@2x.png": "",
  "thumbnail@3x.png": ""
};
